"use client";

import * as React from "react";
import { Landmark } from "lucide-react";
import { cn } from "@/lib/utils";

/** Brand marks for the feed sources; monogram chips stand in where no mark is published. */
export type SourceIconKey =
  | "twitter"
  | "4chan"
  | "truthsocial"
  | "polymarket"
  | "kalshi"
  | "congress"
  | "coingecko"
  | "alpaca"
  | "robinhood";

const BRAND = {
  polymarket: { text: "P", bg: "#2e5cff", fg: "#ffffff" }, // token-guard-allow
  kalshi: { text: "K", bg: "#0fb37d", fg: "#0b1a14" }, // token-guard-allow
  truthsocial: { text: "T", bg: "#5448c8", fg: "#ffffff" }, // token-guard-allow
  coingecko: { text: "CG", bg: "#8dc63f", fg: "#0f1d05" }, // token-guard-allow
  alpaca: { text: "A", bg: "#fcd72b", fg: "#101010" }, // token-guard-allow
  fourchan: "#2e8b3a", // token-guard-allow
  robinhood: "#9fe000", // token-guard-allow
} as const;
const CHIP: Record<string, { text: string; bg: string; fg: string }> = {
  polymarket: BRAND.polymarket,
  kalshi: BRAND.kalshi,
  truthsocial: BRAND.truthsocial,
  coingecko: BRAND.coingecko,
  alpaca: BRAND.alpaca,
};

function XMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" className={className} aria-hidden fill="currentColor">
      <path d="M14.234 10.162 22.977 0h-2.072l-7.591 8.824L7.251 0H.258l9.168 13.343L.258 24H2.33l8.016-9.318L16.749 24h6.993zm-2.837 3.299-.929-1.329L3.076 1.56h3.182l5.965 8.532.929 1.329 7.754 11.09h-3.182z" />
    </svg>
  );
}

function FourChanMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" className={className} aria-hidden fill={BRAND.fourchan}>
      <path d="M11.07 8.82S9.803 1.079 5.145 1.097C2.006 1.109.78 4.124 3.055 4.802c0 0-2.698.973-2.698 2.697 0 1.725 4.274 3.54 10.713 1.32zm1.931 5.924s.904 7.791 5.558 7.991c3.136.135 4.503-2.82 2.262-3.604 0 0 2.74-.845 2.82-2.567.08-1.723-4.105-3.737-10.64-1.82zm-3.672-1.55s-7.532 2.19-6.952 6.813c.39 3.114 3.53 3.969 3.93 1.63 0 0 1.29 2.559 3.002 2.351 1.712-.208 3-4.67.02-10.794zm5.623-2.467s7.727-1.35 7.66-6.008c-.046-3.138-3.074-4.333-3.728-2.051 0 0-1-2.686-2.726-2.668-1.724.018-3.494 4.312-1.206 10.727z" />
    </svg>
  );
}

function RobinhoodMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 24 24" className={className} aria-hidden fill={BRAND.robinhood}>
      <path d="M2.84 24h.53c.096 0 .192-.048.224-.128C7.591 13.696 11.94 8.656 14.67 5.638c.112-.128.064-.225-.096-.225h-4.88a.55.55 0 0 0-.45.225L5.746 9.972c-.514.642-.642 1.236-.642 2.086v4.43c-1.14 3.194-1.862 5.361-2.392 7.32-.032.125.016.192.129.192M20.447.646c-.754-.802-4.157-.834-5.73-.224a3 3 0 0 0-.786.465 41 41 0 0 0-3.323 3.178c-.112.113-.064.225.097.225h5.409c.497 0 .786.289.786.786v6.1c0 .16.128.208.225.064l3.258-4.254c.53-.69.69-.898.835-1.861.192-1.413.08-3.58-.77-4.479m-6.982 16.18 2.231-3.676a.7.7 0 0 0 .064-.29V6.73c0-.16-.112-.225-.224-.097-3.355 3.74-5.971 7.672-8.395 12.407-.06.12.016.225.16.177l5.009-1.54c.565-.174.882-.402 1.155-.852" />
    </svg>
  );
}

const SIZE = { sm: "size-4", md: "size-5", lg: "size-7" } as const;
const TEXT = { sm: "text-[8px]", md: "text-[9px]", lg: "text-[11px]" } as const;

export function SourceIcon({
  source,
  size = "md",
  className,
}: {
  source: string;
  size?: keyof typeof SIZE;
  className?: string;
}) {
  const box = cn(
    "inline-flex shrink-0 items-center justify-center overflow-hidden rounded-[30%]",
    SIZE[size],
    className,
  );
  if (source === "twitter") {
    return (
      <span className={cn(box, "bg-foreground text-background")}>
        <XMark className="size-[62%]" />
      </span>
    );
  }
  if (source === "4chan") {
    return (
      <span className={cn(box, "bg-[var(--color-bull-soft)]")}>
        <FourChanMark className="size-[72%]" />
      </span>
    );
  }
  if (source === "robinhood") {
    return (
      <span className={cn(box, "bg-foreground")}>
        <RobinhoodMark className="size-[66%]" />
      </span>
    );
  }
  if (source === "congress") {
    return (
      <span className={cn(box, "bg-[var(--color-cyan-soft)] text-[var(--color-cyan-fg)]")}>
        <Landmark className="size-[62%]" strokeWidth={2.25} />
      </span>
    );
  }
  const chip = CHIP[source];
  if (chip) {
    return (
      <span
        className={cn(box, "font-mono font-bold leading-none", TEXT[size])}
        style={{ background: chip.bg, color: chip.fg }}
      >
        {chip.text}
      </span>
    );
  }
  return (
    <span
      className={cn(
        box,
        "bg-muted font-mono font-semibold uppercase text-muted-foreground",
        TEXT[size],
      )}
    >
      {source.slice(0, 2)}
    </span>
  );
}
